 itm jsonb; actual jsonb;other_old jsonb;other_new jsonb;
 grading_old jsonb;grading_new jsonb;config_old jsonb;config_new jsonb;changed integer;
BEGIN
 IF (SELECT count(*) FROM public.questions)<>4800 THEN RAISE EXCEPTION 'P0 corpus count mismatch';END IF;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_old FROM public.questions q WHERE id NOT IN ('DS-104-1-30','SW-106-1-29','R-106-1-30','SW-108-2-27','DS-108-2-12');
 SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_old FROM public.questions;
 SELECT to_jsonb(c) INTO config_old FROM public.ai_analysis_job_config c WHERE id=true;
 IF config_old->>'enabled'<>'false' THEN RAISE EXCEPTION 'P0 AI config enabled';END IF;
 FOR itm IN SELECT value FROM jsonb_array_elements(old_rows) LOOP
   SELECT to_jsonb(q) INTO STRICT actual FROM public.questions q WHERE id=itm->>'id' FOR UPDATE;
   IF actual IS DISTINCT FROM itm THEN RAISE EXCEPTION 'P0 before image differs %',itm->>'id';END IF;
 END LOOP;
  UPDATE public.questions SET question='一位機構的督導想要瞭解新進社會工作人員在與案主會談時，技巧運用與介入是否得宜？督導可以要求這位社會工作人員撰寫下列那種形式的個案紀錄？', opt_a='SOAP 紀錄' WHERE id='DS-104-1-30';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI five source row count mismatch DS-104-1-30'; END IF;
  UPDATE public.questions SET opt_a='在訪視前先列出問題清單，會限縮社會工作者的觀察面向', opt_b='在自然情境中發生的訪視，有助於社會工作者與個案建立關係' WHERE id='DS-108-2-12';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI five source row count mismatch DS-108-2-12'; END IF;
  UPDATE public.questions SET opt_a='卡方檢定', opt_b='t 檢定' WHERE id='R-106-1-30';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI five source row count mismatch R-106-1-30'; END IF;
  UPDATE public.questions SET opt_b='中華民國醫務社會服務協會', opt_c='中華民國社會工作師公會全國聯合會' WHERE id='SW-106-1-29';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI five source row count mismatch SW-106-1-29'; END IF;
  UPDATE public.questions SET opt_a='睦鄰公社運動成立時間較慈善組織會社早', opt_b='Mary Richmond 曾經擔任睦鄰公社的親善訪問人員，並且於 1918 年出版一本《社會診斷》的書籍' WHERE id='SW-108-2-27';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'SWSI five source row count mismatch SW-108-2-27'; END IF;
 UPDATE public.questions SET analysis_status='review' WHERE id IN ('DS-104-1-30','SW-106-1-29','R-106-1-30','SW-108-2-27','DS-108-2-12') AND analysis_status='pending';
 GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>5 THEN RAISE EXCEPTION 'P0 stale analysis quarantine failed';END IF;
 FOR itm IN SELECT value FROM jsonb_array_elements(new_rows) LOOP
   SELECT to_jsonb(q) INTO STRICT actual FROM public.questions q WHERE id=itm->>'id';
   IF actual IS DISTINCT FROM itm THEN RAISE EXCEPTION 'P0 after image differs %',itm->>'id';END IF;
 END LOOP;
 SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_new FROM public.questions q WHERE id NOT IN ('DS-104-1-30','SW-106-1-29','R-106-1-30','SW-108-2-27','DS-108-2-12');
 SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_new FROM public.questions;
 SELECT to_jsonb(c) INTO config_new FROM public.ai_analysis_job_config c WHERE id=true;
 IF other_old IS DISTINCT FROM other_new THEN RAISE EXCEPTION 'P0 unrelated 4795 rows changed';END IF;
 IF grading_old IS DISTINCT FROM grading_new THEN RAISE EXCEPTION 'P0 grading changed';END IF;
 IF config_old IS DISTINCT FROM config_new THEN RAISE EXCEPTION 'P0 AI job config changed';END IF;
 IF EXISTS(SELECT 1 FROM public.questions WHERE analysis_status='pending') THEN RAISE EXCEPTION 'P0 pending row leaked';END IF;
 RAISE NOTICE 'SWSI five-row ROLLBACK rehearsal passed: 4795 other full rows & 4800 scoring tuple unchanged';
